import java.util.*;class Solution{public List<Integer> findMinHeightTrees(int n,int[][]e){if(n==1)return Arrays.asList(0);List<Integer>[]g=new List[n];int[]d=new int[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();for(int[]x:e){g[x[0]].add(x[1]);g[x[1]].add(x[0]);d[x[0]]++;d[x[1]]++;}Queue<Integer>q=new ArrayDeque<>();for(int i=0;i<n;i++)if(d[i]==1)q.add(i);int left=n;while(left>2){int z=q.size();left-=z;while(z-->0){int u=q.remove();for(int v:g[u])if(--d[v]==1)q.add(v);}}return new ArrayList<>(q);}}
